package blockbranch.realistic;
import java.util.*;
public class FrozenRiverCheck{public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var p=blockbranch.realistic.FrozenRiverFixtures.fixture(d,seed);int ice=0;var arrays=new LinkedHashMap<String,int[]>();for(int cz=(p.z()>>4)-1;cz<=(p.z()>>4)+1;cz++)for(int cx=(p.x()>>4)-1;cx<=(p.x()>>4)+1;cx++){var a=FrozenRiver.column(cx,cz,d,c);arrays.put(cx+","+cz,a);for(int v:a){ice++;int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,x=cx*16+(k&15),z=cz*16+(k>>4&15),y=(k>>8)+TerrainShape.FLOOR;var s=d.sample(x,z);if((v&blockbranch.cubic.CanopyLayer.STATE_MASK)!=91||y!=s.waterLevel()-1||s.height()>=y-1||!FrozenRiver.point(x,z,d,c)||d.oceanWater(x,z,s)||d.terminalLakeWater(x,z,s)||RoutedRiver.contains(seed,x,z,d,c))throw new AssertionError("Ice domain/source liquid/temperature");}}var keys=new ArrayList<>(arrays.keySet());Collections.reverse(keys);for(var k:keys){var q=k.split(",");if(!Arrays.equals(arrays.get(k),FrozenRiver.column(Integer.parseInt(q[0]),Integer.parseInt(q[1]),d,c)))throw new AssertionError("Ice order/seam consistency");}if(ice<16||ice>2304)throw new AssertionError("Bounded nonempty ice");var old=blockbranch.realistic.RiverChannelFixtures.fixture(d,seed);if(FrozenRiver.contains(old.x(),old.z(),d,c))throw new AssertionError("Retained planted fringe");System.out.println("FROZEN_RIVER seed="+seed+" point="+p+" ice="+ice+" water="+d.sample(p.x(),p.z()).waterLevel()+" T="+c.sample(p.x(),p.z(),d::sample).meanTemperatureC());}System.out.println("FROZEN_RIVER_EXACT_WATER_CLIMATE_ORDER_PASS");}}
